```python
import random

def is_prime(num):
    """Checks if a number is prime."""
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def generate_prime():
    """Generates a random prime number between 1 and 100."""
    while True:
        num = random.randint(1, 100)
        if is_prime(num):
            return num

prime_number = generate_prime()
print(f"Generated prime number: {prime_number}")

```

Is mein `is_prime` function check karta hai ki number prime hai ya nahin, aur `generate_prime` function loop karta hai jab tak ek prime number nahin mil jata.  Koi sawal ho to pooch lena.

Here's a JavaScript script that takes a number as input (between 1 and 100) and determines if it's a prime number:

```javascript
function isPrime(num) {
  // Prime numbers are whole numbers greater than 1
  if (num <= 1) return false;
  // Check divisibility from 2 up to the square root of the number
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) return false;
  }
  return true;
}

function checkPrime() {
  const num = parseInt(document.getElementById("numberInput").value);
  if (isNaN(num) || num < 1 || num > 100) {
    document.getElementById("result").textContent = "Please enter a number between 1 and 100.";
    return;
  }

  const result = isPrime(num) ? " is a prime number." : " is not a prime number.";
  document.getElementById("result").textContent = num + result;
}

//This creates the input form in HTML:
document.body.innerHTML = `
  <h1>Prime Number Checker</h1>
  <input type="number" id="numberInput" placeholder="Enter a number (1-100)">
  <button onclick="checkPrime()">Check</button>
  <p id="result"></p>
`;
```

